text:
/* SilbaÄtno repertoire homepage — scoped, responsive and independent from Forge theme. */
.tc-tiddler-frame[data-tiddler-title="Akustisk-Elektrisk · Kaffepausen"] .tc-tiddler-title .tc-title {display:none;}
.duo-home {font-family:inherit;color:#243547;line-height:1.55;max-width:1100px;margin:0 auto;container-type:inline-size;container-name:duo-home;}
.duo-home * {box-sizing:border-box;}
.duo-hero {display:grid;grid-template-columns:minmax(0,1fr) minmax(255px,.82fr);gap:0;background:#142c40;border-radius:19px;overflow:hidden;box-shadow:0 12px 35px rgba(16,36,53,.17);}
.duo-hero-copy {padding:clamp(28px,5vw,56px);display:flex;flex-direction:column;justify-content:center;color:#fff;min-width:0;container-type:inline-size;container-name:duo-copy;}
.duo-eyebrow {margin:0 0 15px!important;font-size:.77rem;letter-spacing:.14em;font-weight:750;color:#f0cb80;}
.duo-hero h1 {font-size:clamp(1.45rem,16cqi,4.9rem)!important;line-height:1.04;letter-spacing:-.05em;color:#fff!important;margin:0 0 6px!important;white-space:nowrap;overflow-wrap:normal;word-break:normal;max-width:100%;}
.duo-hero-subtitle {font-size:clamp(1.35rem,2.2vw,1.65rem);font-weight:520;margin:0 0 16px!important;color:#e6e4d5;}
.duo-lead {font-size:1rem;max-width:42ch;color:#e0e9ef;margin:0 0 24px!important;}
.duo-actions {display:flex;align-items:center;gap:9px;flex-wrap:nowrap;margin-bottom:15px;min-width:0;}
.duo-actions a {display:inline-flex;align-items:center;justify-content:center;border-radius:9px;text-decoration:none!important;font-size:1rem;font-weight:750;line-height:1.25;}
.duo-actions a.duo-action {position:relative;flex:0 0 44px;width:44px;height:44px;min-width:44px;min-height:44px;padding:0!important;border-radius:10px;touch-action:manipulation;}
.duo-action svg {display:block;width:21px;height:21px;fill:none;stroke:currentColor;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round;pointer-events:none;}
.duo-action-label {position:absolute!important;width:1px!important;height:1px!important;overflow:hidden!important;clip-path:inset(50%);white-space:nowrap;padding:0!important;margin:-1px!important;border:0!important;}
.duo-actions a.duo-action:hover,.duo-actions a.duo-action:focus-visible {transform:translateY(-1px);}
.duo-actions a.duo-action:focus-visible {outline:3px solid #f2cf85;outline-offset:3px;}
.duo-primary,.duo-primary:visited {background:#ecd18f;color:#152c3b!important;}
.duo-secondary,.duo-secondary:visited {background:transparent;color:#fff!important;border:1px solid #b5cad5;}
.duo-primary:hover {background:#ffe0a0;}
.duo-secondary:hover {background:#ffffff22;}
.duo-hero-hint {font-size:.83rem;color:#c6d7e0;margin:0!important;line-height:1.4;}
.duo-hero-photo {position:relative;min-height:310px;margin:0!important;background:radial-gradient(circle at 70% 30%,#527486,#203f50 65%);}

.duo-hero-photo figcaption {position:absolute;left:0;right:0;bottom:0;padding:13px 16px;color:#fff;background:linear-gradient(transparent,#0009);font-size:.75rem;}
.duo-hero-photo a,.duo-hero-photo a:visited {color:#fff;text-decoration:underline;}
.duo-metrics {display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;margin:20px 0 28px;}
.duo-metrics>.duo-metric {display:block;padding:17px 20px;border:1px solid #dfe9e8;border-radius:12px;background:#f5f9f7;color:inherit;text-decoration:none!important;min-width:0;cursor:pointer;transition:border-color .15s,background-color .15s,box-shadow .15s;}
.duo-metrics>.duo-metric:hover {border-color:#77a9a1;background:#edf6f3;box-shadow:0 4px 12px rgba(16,48,46,.09);}
.duo-metrics>.duo-metric:focus-visible {outline:3px solid #186e6c;outline-offset:3px;}
.duo-metrics strong {display:block;font-size:2rem;font-weight:770;line-height:1.1;color:#176b66;}
.duo-metrics span {display:block;font-size:.89rem;color:#556a77;margin-top:4px;}
.duo-intro {padding:0 2px;margin-bottom:22px;}
.duo-home h2 {font-size:clamp(1.28rem,2vw,1.6rem)!important;line-height:1.23;font-weight:720;color:#1c3b4d;margin:0 0 10px!important;}
.duo-intro p {max-width:78ch;color:#49606c;margin:0!important;}
.duo-section {background:#fff;border:1px solid #dce6e5;border-radius:15px;padding:clamp(18px,2.8vw,29px);box-shadow:0 5px 16px rgba(19,44,55,.05);}
.duo-section-heading {display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap;padding-bottom:13px;border-bottom:1px solid #e8efef;margin-bottom:10px;}
.duo-section-heading h2 {margin:0!important;}
.duo-section-heading>span {font-size:.82rem;color:#647d83;border-radius:30px;background:#edf3f1;padding:5px 11px;}
.duo-track-list {list-style:none!important;margin:0!important;padding:0!important;display:grid;grid-template-columns:minmax(0,1fr);gap:6px;counter-reset:none;}
.duo-track-list li {display:flex;align-items:center;gap:11px;padding:13px 3px;border-bottom:1px solid #edf1f1;min-width:0;margin:0!important;}
.duo-track-list li a {font-size:.95rem;font-weight:630;flex:1;min-width:0;overflow-wrap:anywhere;color:#175e6c;text-decoration:none;}
.duo-track-list li a:hover {text-decoration:underline;}
.duo-index {display:inline-flex;flex:0 0 30px;width:30px;height:30px;border-radius:8px;background:#f3e9cf;color:#68562c;font-size:.78rem;font-weight:760;align-items:center;justify-content:center;}
.duo-track-meta {font-size:.72rem;color:#83999c;white-space:nowrap;}
.duo-secondary-grid {display:grid;grid-template-columns:1fr 1fr;gap:15px;margin-top:15px;}
.duo-secondary-grid .duo-track-list {grid-template-columns:1fr;}
.duo-secondary-grid p {font-size:.9rem;color:#657980;margin:4px 0 9px!important;}
.duo-note {background:#f7f9f7;border-left:4px solid #bd9c50;padding:20px 22px;margin-top:18px;border-radius:0 12px 12px 0;}
.duo-note h2 {font-size:1.1rem!important;}
.duo-note p {font-size:.92rem;color:#526772;margin:7px 0!important;}
.duo-note a {font-weight:680;}
@media(max-width:1020px) {.duo-track-meta {display:none;}}
/* The wiki's story/sidebar layout can narrow the hero without narrowing
   the browser viewport: respond to the actual article width instead. */
@container duo-home (max-width:690px) {
 .duo-hero {grid-template-columns:minmax(0,1fr);}
 .duo-hero-copy {padding:clamp(22px,5cqi,34px);}
 .duo-hero-photo {min-height:190px;max-height:300px;}
 /* Preserve the musicians' faces when a narrow story stacks the photo. */
 .duo-photo-visual {min-height:190px;max-height:300px;background-position:center top;}
 .duo-track-list,.duo-secondary-grid {grid-template-columns:minmax(0,1fr);}
}
@media(max-width:750px) {
 .duo-hero {grid-template-columns:1fr;}
 .duo-hero-copy {padding:28px;}
 .duo-hero-photo {min-height:190px;max-height:260px;}
 .duo-photo-visual {min-height:190px;max-height:260px;background-position:center top;}
 .duo-track-list,.duo-secondary-grid {grid-template-columns:1fr;}
 .duo-metrics {gap:8px;}
 .duo-metrics>.duo-metric {padding:12px;}
 .duo-metrics strong {font-size:1.65rem;}
 .duo-metrics span {font-size:.76rem;}
}
@media(max-width:380px) {.duo-metrics {grid-template-columns:1fr;} }

/* Shared dynamic WikiText list, used on homepage and the three metric destinations. */
.duo-generated-list {max-width:930px;margin:0 auto;}
.duo-generated-list>p {color:#506772;}
.duo-generated-list .duo-track-list {margin-top:14px!important;}
.duo-generated-list .duo-list-back {margin:22px 0 0!important;}
.duo-generated-list .duo-list-back a {font-weight:650;color:#175e6c;}
.duo-track-meta.duo-track-pending {display:inline-flex;color:#8d6225;font-size:.72rem;white-space:nowrap;}
.duo-track-list li .duo-track-link {font-weight:640;}
@media(max-width:520px) {.duo-generated-list .duo-track-row {flex-wrap:wrap;}.duo-generated-list .duo-track-pending {margin-left:41px;}}

.duo-home .duo-hero h1{font-size:clamp(1.6rem,11cqi,4.2rem)!important;white-space:normal;letter-spacing:-.045em;word-break:normal;overflow-wrap:normal;hyphens:manual}
.duo-hero-copy{padding:clamp(22px,4.1vw,44px)}
.duo-hero-photo{align-self:stretch;min-height:0;overflow:hidden;display:grid;align-content:center;background:#152b39}
.duo-hero-photo img{display:block;width:100%;height:auto;max-width:100%;margin:0}
.duo-hero-photo figcaption{position:static;background:#152b39;color:#fff;padding:6px 12px;font-size:.76rem}
.duo-books{display:flex;gap:.55rem;flex-wrap:wrap}.duo-books a{border:1px solid #b5cad5;color:white!important;text-decoration:none!important;padding:6px 12px;border-radius:8px;font-weight:650}
.duo-books a:first-child{background:#ecd18f;color:#142c40!important;border-color:#ecd18f}
.duo-books a:focus-visible,.duo-rows a:focus-visible{outline:3px solid #d69936;outline-offset:2px}
.duo-rows{list-style:none!important;padding:0!important;margin:0!important}.duo-rows li{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap;padding:.7rem 0;border-bottom:1px solid #d5dcd9}.duo-rows li:last-child{border:0}
.duo-rows a{font-size:1.06rem;font-weight:650}.duo-rows span{font-size:.93rem;color:#485c67}.duo-foot{font-size:.93rem;color:#425761}.duo-foot a{font-weight:600}
@container duo-home (max-width:690px){.duo-hero-photo{max-height:none;min-height:0}.duo-hero-photo img{max-height:300px;object-fit:contain}}
